import { DurableObject } from 'cloudflare:workers';
import { Lifecycle } from 'agents/lifecycle';
import { Scheduler } from 'agents/schedules';

const THIRTY_DAYS_MS = 30 * 24 * 3600 * 1000;

// Workers run in UTC, so this fires daily at 03:00 UTC.
const COMPACT_CRON = '0 3 * * *';

// A plain Durable Object (not an Agent). Other Workers call hit() and count() over RPC.
// Lifecycle owns alarm(); don't define alarm() here.
export class Counter extends DurableObject {
  scheduler = new Scheduler({
    callbacks: {
      compact: () => this.compact(),
    },
  });

  lifecycle = Lifecycle.install(this).use(this.scheduler);

  constructor(ctx, env) {
    super(ctx, env);
    ctx.storage.sql.exec('CREATE TABLE IF NOT EXISTS hits (at INTEGER NOT NULL)');
  }

  async onStart() {
    // Cron schedules are idempotent, so re-registering on every start is a no-op.
    await this.scheduler.set(COMPACT_CRON, 'compact');
  }

  async hit() {
    // Native RPC bypasses lifecycle startup, so start it explicitly to register the schedule.
    await this.lifecycle.start();
    this.ctx.storage.sql.exec('INSERT INTO hits (at) VALUES (?)', Date.now());
    return this.count();
  }

  async count() {
    await this.lifecycle.start();
    return this.ctx.storage.sql.exec('SELECT COUNT(*) AS n FROM hits').one().n;
  }

  // Deletes hits older than 30 days.
  async compact() {
    this.ctx.storage.sql.exec('DELETE FROM hits WHERE at < ?', Date.now() - THIRTY_DAYS_MS);
  }
}

